<script>
(() => { const root=document.documentElement, button=document.querySelector('.toggle'); const key='sigps-sidebar-collapsed'; if(localStorage.getItem(key)==='true') root.classList.add('sidebar-collapsed'); const sync=()=>{const open=!root.classList.contains('sidebar-collapsed');button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Contraer menú':'Expandir menú');button.title=open?'Contraer menú':'Expandir menú'};sync();button.addEventListener('click',()=>{root.classList.toggle('sidebar-collapsed');localStorage.setItem(key,String(root.classList.contains('sidebar-collapsed')));sync()}) })();
</script>
